s = input()
pairs = {")": "(", "]": "[", "}": "{"}
st = []
ok = True
for ch in s:
    if ch in "([{":
        st.append(ch)
    elif ch in pairs:
        if not st or st.pop() != pairs[ch]:
            ok = False
            break
print("YES" if ok and not st else "NO")

